problems.solution:
class Solution:
    def twoSum(self, nums: list[int], target: int) -> list[int]:
        n = len(nums)

        # Outer loop picks the first element
        for i in range(n):
            # Inner loop picks the second element (always after i)
            for j in range(i + 1, n):
                if nums[i] + nums[j] == target:
                    return [i, j]

        return []
